// ---------------------------------------------------------------- clips
const src = JSON.parse(fs.readFileSync(new URL("./2026-10-clip-sources.json", import.meta.url), "utf8"));
const LICENSE = (s) => (/public|cc0/i.test(s.license) ? (s.license === "CC0" ? "CC0 (gemeinfrei)" : "Gemeinfrei") : `${s.license}, ${s.by} – bearbeitet (Ausschnitt, Hochformat)`);
const AUTHOR = { earthrise: "NASA / Goddard Space Flight Center", wright: "Unbekannt (gemeinfrei)", polarlicht: "NASA Scientific Visualization Studio", titanic: "British Pathé", buero: "Coronet Instructional Films", einkauf: "Hillsdale Shopping Center", muenzen: "United States Mint", banknoten: "Europäische Zentralbank", gepard: "Gregory Wilson", bienen: "OakleyOriginals", stare: "Karen Roe", orchester: "University of Colorado Boulder College of Music", lumiere: "Auguste und Louis Lumière" };

/** key = entry in the source list; cut = [start, end, mode, x, extra] */
const clip = (key, id, category_id, min_age, cut, de, en, quiz, tags) => {
  const s = { ...src[key], by: AUTHOR[key] ?? src[key].author };
  const [start, end, mode = "crop", x = 0.5, extra = {}] = cut;
  return {
    id, category_id, min_age, tags, title: de[0], hook: de[1], description: de[2], captions: de[3], en: { title: en[0], hook: en[1], description: en[2], captions: en[3] }, quiz,
    creator_name: AUTHOR[key] ?? s.author, license: LICENSE(s), source: { name: s.source, url: s.page }, format: "footage",
    production: { provider: "external", cache: key, source_url: s.orig && key !== "gepard" ? s.url : s.url, start, end, mode, x, ...extra },
  };
};

